(() => {
  'use strict';
  const D=window.MAX_DATA, R=window.MAX_REFERENCES;
  const main=document.querySelector('main'), viewer=document.querySelector('#viewer'), cardDialog=document.querySelector('#card-dialog');
  const ref=id=>R.find(r=>r.id===id), level=slug=>D.levels.find(l=>l.slug===slug);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pad=n=>String(n).padStart(2,'0');
  const state={selected:'gold',pose:'family-gold',campaign:'supplied-1',device:'desktop',filter:'all',search:'',annotation:0,viewerItems:[],viewerIndex:0,zoom:1,fit:{w:0,h:0},lastFocus:null};
  const img=(id,cls='',eager=false)=>{const r=ref(id);return `<img class="${cls}" src="${r.image}" alt="${esc(r.description)}" width="${r.width}" height="${r.height}" loading="${eager?'eager':'lazy'}" decoding="async">`;};
  const zoomButton=id=>`<button type="button" class="circle-button image-open" data-image="${id}" aria-label="Inspect ${esc(ref(id).title)}">↗</button>`;
  const badge=(l,cls='')=>`<img class="${cls}" src="${l.badge}" alt="${esc(l.name)} emblem — ${esc(l.wingLabel.toLowerCase())}" width="512" height="512" loading="lazy">`;
  const selectOptions=selected=>D.levels.map(l=>`<option value="${l.slug}" ${selected===l.slug?'selected':''}>${pad(l.number)} · ${l.name}</option>`).join('');
  const sourceTag=text=>`<span class="source-label">${text}</span>`;
  const I=window.MAX_INTRO_VIEWS.create({R,esc,img});
  const C=window.MAX_COLLECTION_VIEWS.create({D,R,esc,badge,I});
  const S=window.MAX_STUDIO_VIEWS.create({D,R,esc,badge,img});
  const P=window.MAX_PRESENTATION.create({D,R,ref,level,img,badge,zoomButton,esc,C,S,I});
  function renderIntro(){return P.intro();}
  function renderLanding(id){const supplied=/^supplied-[1-7]$/.test(id||''),concept=window.MAX_AMBASSADOR.campaigns.some(c=>c.id===id);state.campaign=supplied||concept?id:'supplied-1';return S.landing(state.campaign,state.device);}
  function renderCharacterDetail(slug){const l=level(slug),w=l&&D.wardrobes.find(w=>w.id===l.wardrobeId);if(!l||!w)return renderStory();return `<div class="wrap character-route-page"><div class="detail-top"><a class="back-link" href="#story">← Back to all characters</a></div><section class="character-route-detail card-modal-layout"><figure class="card-modal-art">${C.character(l,'',true)}<figcaption>${esc(w.name)} · complete character artwork</figcaption></figure><div class="card-modal-copy character-route-copy"><span class="eyebrow">Gesture & pose / ${w.slugs.length} ${w.slugs.length===1?'rank':'ranks'}</span><h1>${esc(w.pose)}</h1><p class="card-modal-lead">${esc(w.gesture)}</p><div class="card-modal-ranks"><span class="eyebrow">Associated ranks</span><div>${w.slugs.map(s=>{const rank=level(s);return `<span>${badge(rank)}<small>${esc(rank.name)}</small></span>`;}).join('')}</div></div><dl class="card-modal-summary"><div><dt>Gesture</dt><dd>${esc(w.gesture)}</dd></div><div><dt>Where Max helps</dt><dd>${esc(w.context)}</dd></div><div><dt>Voice</dt><dd>${esc(w.voice||'“Let me show you the details.”')}</dd></div><div><dt>Progression</dt><dd>${esc(l.outfit.change)}</dd></div></dl>${garmentList(w.garments)}<p class="card-modal-note">${esc(w.influence)}</p><div class="card-modal-actions"><a class="button" href="#detail/${l.slug}">Open the costume study →</a><button type="button" class="text-link" data-outfit="${l.slug}">Enlarge artwork ↗</button></div></div></section></div>`;}
  function renderStory(arg){if(arg&&arg!=='motion'&&level(arg))return renderCharacterDetail(arg);return `<div class="wrap"><header class="page-heading split"><div><span class="eyebrow">The character / Identity & intention</span><h1>A gentleman.<br><i>A familiar guide.</i></h1></div></header>
    <section class="story-opener"><figure class="story-image">${C.character('gold','',true)}<button type="button" class="circle-button image-open" data-outfit="gold" aria-label="Inspect Gold outfit">↗</button></figure><div class="story-copy"><span class="eyebrow">His role in the story</span><h2>Max makes the<br>programme <i>personal.</i></h2><p>The supplied brief introduces Max as the member host: one familiar face who explains the loyalty programme, shows visitors where they stand and acknowledges a new level.</p><p>His calm expression and relaxed posture make formal clothing feel approachable. Silver hair and a white beard give him a mature identity; the spectacles and long-legged silhouette make that identity easy to recognize. Open palms and directional gestures let him guide, explain and present.</p><div class="personality"><span class="tag">Calm</span><span class="tag">Helpful</span><span class="tag">Straight-talking</span><span class="tag">Dry wit</span></div></div></section>${motion()}
    <section class="section-spaced rule"><div class="section-head"><div><span class="eyebrow">The recognizable details</span><h2>Identity, in close-up.</h2></div><p>What the artwork shows, and how those visible choices can support the host’s personality.</p></div><div class="craft-grid"><figure><div class="craft-closeup">${img('ref-19','crop-face')}<button type="button" class="circle-button" data-image="ref-19" data-focus="50,9" aria-label="Inspect face and spectacles">↗</button></div><figcaption><strong>The face</strong>Silver swept hair, black frames, a white beard and a restrained smile. Visible features, retained across the collection.</figcaption></figure><figure><div class="craft-closeup">${img('ref-24','crop-badge')}<button type="button" class="circle-button" data-image="ref-24" data-focus="57,20" aria-label="Inspect the NB mark and chest emblem">↗</button></div><figcaption><strong>Two distinct signs</strong>The NB mark identifies the host. The small shield expresses the loyalty level, below it on Max’s left chest.</figcaption></figure><figure><div class="craft-closeup">${img('ref-24','crop-cuff')}<button type="button" class="circle-button" data-image="ref-24" data-focus="27,46" aria-label="Inspect cuff and cane">↗</button></div><figcaption><strong>The finishing gesture</strong>The cuff, fastening and hand work together. The original cane pose remains in the archive, alongside new hands-free guiding gestures.</figcaption></figure></div></section>
    <section class="voice-demo section-spaced rule"><div><span class="eyebrow">Max, as your assistant</span><h2>Present.<br><i>Never intrusive.</i></h2><p class="quote">“A little guidance.<br>Whenever you need it.”</p><p class="muted">A proposed interaction: Max waits at the edge of the interface. Visitors choose when to open his explanation.</p>${sourceTag('Dialogue & interface example · proposed')}</div><div class="assistant-preview"><div class="speech"><span class="eyebrow">MAX / YOUR HOST</span><p>Curious about the wings on your shield?</p><a class="text-link" href="#wardrobe/ace">See the emblem family <span aria-hidden="true">↗</span></a></div>${C.character('champion')}</div></section>
    ${C.cardGrid('character',{title:'A gesture for every moment.',eyebrow:'Character variations / The ambassador at work',intro:'Welcome, explain, acknowledge and present. Explore the same Max in a complete family of useful poses.'})}<section class="craft-benchmark section-spaced rule"><figure>${img('ref-15')}<figcaption class="caption">Supplied clothing reference · embroidery and accessory benchmark</figcaption></figure><div><span class="eyebrow">A period-inspired vocabulary</span><h2>Rich in detail.<br><i>Considered in character.</i></h2><p>Cutaway fronts, waistcoats and cravats give the collection Regency-inspired cues. Long coats, raised collars and ornate borders contribute a Victorian/Gothic-inspired vocabulary. The cape adds theatrical scale.</p><p>These are stylistic readings of the visible designs. The references do not establish dates, fabrics, stitch methods or unseen garment construction.</p><p>The black-and-burgundy reference informs embroidery, fastenings and a watch chain. The newest navy-and-cream reference informs the whole Regency ensemble, including its high-waisted cream trousers. These details are carried into labelled new proposals.</p><a class="text-link" href="#detail/centurion-elite">Inspect the ceremonial outfit <span aria-hidden="true">↗</span></a></div></section>
  </div>`;}
  function familyPanel(l){const f=D.families.find(f=>f.id===l.family);return `<section class="family-panel" aria-labelledby="family-title"><div class="family-panel-head"><div><span class="eyebrow">${f.id==='foundation'?'Six individual designs':'Same wardrobe / Evolving wings'}</span><h2 id="family-title">${esc(f.name)}${f.id==='foundation'?'.':' family.'}</h2><p>${esc(f.note)}</p></div><div class="select-group"><label for="family-select">Badge family</label><select id="family-select">${D.families.map(x=>`<option value="${x.id}" ${x.id===l.family?'selected':''}>${x.name}</option>`).join('')}</select></div></div><div class="family-lineup ${f.id==='foundation'?'foundation':''}">${f.slugs.map(s=>{const v=level(s);return `<button type="button" class="family-variant" data-level="${s}" aria-pressed="${s===l.slug}"><span class="variant-number">${pad(v.rank)}</span>${badge(v)}<h3>${v.name}</h3><span>${v.wingLabel.toUpperCase()}</span><span>LEVEL ${pad(v.number)}</span></button>`;}).join('')}</div></section>`;}
  function missing(l){return `<div class="missing-outfit"><div>${badge(l)}<span class="eyebrow">Level ${pad(l.number)} / ${l.name}</span><h3>An outfit still to come.</h3><p>No matching full-length outfit was supplied for ${l.name}. Its official emblem is available to inspect.</p><a class="text-link" href="#references/sources">View the collection notes <span aria-hidden="true">↗</span></a></div></div>`;}
  function lookRail(){return C.cardGrid('collection',{title:'Fifteen considered wardrobes.',eyebrow:'The full collection',intro:'Two cards per row, with the complete outfit direction, associated ranks and a direct route to the detailed study.'});}
  function renderWardrobe(slug){
    const l=level(slug)||level(state.selected);state.selected=l.slug;
    return `<div class="wrap"><header class="page-heading compact-heading"><div><span class="eyebrow">Wardrobe / 15 designs · 28 levels</span><h1>One wardrobe.<br><i>A family of ranks.</i></h1></div></header>${lookRail()}</div>`;
  }
  function missingChange(l){const f=D.families.find(f=>f.id===l.family);const i=f.slugs.indexOf(l.slug);return i>0?`Within this family, ${l.name} follows ${level(f.slugs[i-1]).name}: the core remains recognizable and the wing treatment changes. A clothing comparison needs the missing outfit artwork.`:'This is the first design in the displayed family. Its outfit and costume progression still need a matching reference.';}
  function annotationPanel(l,index){const a=l.outfit.annotations[index];return `<div><span class="eyebrow">Detail ${pad(index+1)} / Visible in the artwork</span><h2>${a.title}</h2><p>${a.text}</p><button type="button" class="text-link" data-outfit="${l.slug}" data-focus="${a.x},${a.y}">Inspect this detail <span aria-hidden="true">↗</span></button></div><dl class="annotation-properties"><div><dt>Appearance & finish</dt><dd>${a.finish}</dd></div><div><dt>Character reading · proposed</dt><dd>${a.meaning}</dd></div><div><dt>Change in the collection</dt><dd>${a.delta}</dd></div><div><dt>Style context</dt><dd>${l.outfit.influence}</dd></div></dl>`;}
  function wardrobeBadgeReference(l){const w=D.wardrobes.find(w=>w.id===l.wardrobeId);return `<section class="wardrobe-badge-reference" aria-labelledby="wardrobe-badge-title"><div><span class="eyebrow">Badge reference / This wardrobe only</span><h2 id="wardrobe-badge-title">${esc(w.name)} ranks.</h2><p>${w.slugs.length===1?'This wardrobe belongs to one rank.':'The outfit stays the same while the official emblem changes across these ranks.'}</p></div><div class="wardrobe-badge-list">${w.slugs.map(slug=>{const rank=level(slug);return `<button type="button" data-level="${slug}" aria-pressed="${slug===l.slug}">${badge(rank)}<span><strong>${esc(rank.name)}</strong><small>${esc(rank.wingLabel)}</small></span></button>`;}).join('')}</div></section>`;}
  function renderDetail(slug){
    const l=level(slug)||level(state.selected);state.selected=l.slug;state.annotation=0;
    return `<div class="wrap"><div class="detail-top"><a class="back-link" href="#wardrobe">← Back to all wardrobes</a></div><header class="detail-title"><div><span class="eyebrow">Costume study / Level ${pad(l.number)}</span><h1>${l.name}<i>.</i></h1></div><p>${l.outfit.subtitle} Select a numbered garment line or enlarge the artwork.</p></header><section aria-label="Annotated ${l.name} outfit">${C.annotated(l)}<div class="detail-controls"><button type="button" class="button secondary" data-outfit="${l.slug}">View complete look & zoom ↗</button><button type="button" class="button secondary" data-badge="${l.slug}">Inspect the official emblem ↗</button></div><div class="annotation-inspector" id="annotation-panel" aria-live="polite">${annotationPanel(l,0)}</div></section>${C.rankSummary(l)}${P.completeWardrobe(l.outfit)}${wardrobeBadgeReference(l)}</div>`;
  }
  function poseContent(id){const p=D.poses.find(p=>p.id===id)||D.poses[0];state.pose=p.id;return `<figure class="pose-figure">${p.level?C.character(p.level,'',true):img(p.ref,'',true)}${p.level?`<button type="button" class="circle-button image-open" data-outfit="${p.level}" aria-label="Inspect this character pose">↗</button>`:zoomButton(p.ref)}</figure><div class="pose-text"><span class="eyebrow">Gesture ${pad(D.poses.indexOf(p)+1)} / ${p.status||'Supplied pose study'}</span><h2>${p.title}<i>.</i></h2><dl><dt>What the artwork shows</dt><dd>${p.gesture}</dd><dt>Proposed interface context</dt><dd>${p.context}</dd></dl><blockquote>${p.voice}</blockquote><p class="fine-note">Proposed dialogue. ${p.note}</p></div>`;}
  function poseLevel(p){const mapped={
    'ambassador-welcome':'gold','ambassador-explain':'champion','ambassador-present':'reserve',composed:'ruby',welcome:'gold',present:'ruby',explain:'black-diamond'
  };return level(p.level||mapped[p.id]);}
  function poseCards(){return D.poses.map((p,i)=>{const matched=poseLevel(p);return `<button type="button" class="pose-study-card" data-pose="${p.id}" aria-haspopup="dialog"><span class="card-corner-badge" data-card-badge="${matched.slug}">${badge(matched)}<small>${esc(matched.name)}</small></span><span class="pose-card-art">${p.level?C.character(p.level,'',false,false):img(p.ref)}</span><span class="pose-card-copy"><span class="eyebrow">Gesture ${pad(i+1)}</span><strong>${p.title}</strong><span>${p.status||'Supplied pose study'}</span></span></button>`;}).join('');}
  function motion(){return `<section class="section-spaced rule" id="motion"><div class="section-head"><div><span class="eyebrow">Motion / Character film</span><h2>Max in <i>motion.</i></h2></div></div><div class="motion-grid ${D.motion.length===1?'single':''}">${D.motion.map(m=>`<article class="motion-slot">${m.src?`<video controls preload="metadata" playsinline poster="${ref(m.poster).image}" aria-label="Max: ${m.name}"><source src="${esc(m.src)}" type="video/mp4">${m.captions?`<track default kind="captions" src="${esc(m.captions)}" srclang="en" label="English">`:''}Your browser cannot play this video. <a href="${esc(m.src)}">Download the clip</a>.</video>`:`<div class="motion-still">${m.level?C.character(m.level):img(m.poster)}<span>Still reference · video needed</span></div>`}<h3>${m.name}</h3><p>${m.need}</p></article>`).join('')}</div></section>`;}
  function renderPoses(id){if(D.poses.some(p=>p.id===id))state.pose=id;return `<div class="wrap"><header class="page-heading"><div><span class="eyebrow">Pose & gesture / Body language</span><h1>A gesture says<br><i>just enough.</i></h1></div></header>${S.faceRail()}<div class="section-head section-spaced pose-library-heading"><div><span class="eyebrow">The complete body language</span><h2>Poses, gestures and posture.</h2></div><div class="pose-library-copy"><a class="text-link" href="#build/build-front">See new body-angle studies ↗</a></div></div><div class="pose-card-grid" aria-label="Character gesture studies">${poseCards()}</div></div>`;}
  function sourceNotes(){return P.sources();}
  function filteredRefs(){return R.filter(r=>(state.filter==='all'||r.roles.includes(state.filter))&&(!state.search||`${r.title} ${r.description} ${r.files.join(' ')}`.toLowerCase().includes(state.search.toLowerCase())));}
  function referenceItems(){const list=filteredRefs();return list.length?list.map(r=>`<article class="reference-item"><button type="button" class="reference-image" data-gallery-image="${r.id}" aria-label="Inspect ${esc(r.title)}"><img src="${r.thumb}" alt="${esc(r.description)}" width="${r.width}" height="${r.height}" loading="lazy" decoding="async"><span aria-hidden="true">↗</span></button><span class="eyebrow">${r.id.replace('ref-','Reference ')} / ${r.roles.join(' · ')}</span><h3>${r.title}</h3><p>${r.description}</p><details><summary>${r.origin} · ${r.files.length} source file${r.files.length===1?'':'s'}</summary><ul>${r.files.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><a class="source-file" href="${r.original}" target="_blank" rel="noopener">Open unchanged original ↗</a></details></article>`).join(''):'<p class="archive-empty">No references match this search. Try another word or category.</p>';}
  function renderReferences(){return `<div class="wrap"><header class="page-heading split"><div><span class="eyebrow">The archive / Source material</span><h1>Every reference.<br><i>Every considered detail.</i></h1></div><p>Character studies, complete outfits, emblems, clothing inspiration and interface explorations. The visual record behind Max.</p></header><div class="archive-controls"><div class="archive-filters" aria-label="Filter references">${[['all','All references'],['identity','Identity'],['wardrobe','Wardrobe'],['poses','Pose & gesture'],['badges','Emblems'],['craft','Craft'],['atmosphere','Interface'],['proposals','New proposals']].map(([id,name])=>`<button type="button" class="filter-button" data-filter="${id}" aria-pressed="${state.filter===id}">${name}</button>`).join('')}</div><label><span class="sr-only">Search references</span><input class="archive-search" type="search" placeholder="Search the collection…" value="${esc(state.search)}"></label></div><p class="archive-count" id="archive-count" aria-live="polite">${filteredRefs().length} of ${R.length} unique images · select an image to inspect</p><div class="reference-grid" id="reference-grid">${referenceItems()}</div>
    <section class="section-spaced"><div class="section-head"><div><span class="eyebrow">The official emblems / Figma export</span><h2>Twenty-eight levels.<br><i>A shared visual language.</i></h2></div><p>Open any badge to inspect its exact gemstone, frame and wings. Family comparisons live in the wardrobe explorer.</p></div><div class="badge-atlas">${D.levels.map(l=>`<button class="atlas-item" type="button" data-badge="${l.slug}" aria-label="Inspect ${l.name} official emblem">${badge(l)}<strong>${l.name}</strong><span>${l.wingLabel}</span></button>`).join('')}</div></section>${sourceNotes()}</div>`;}
  function route(){
    const hash=location.hash.slice(1);if(hash==='main'){main.focus();return;}
    const [view='intro',arg]=hash.split('/');
    const previous=main.dataset.view;const oldScroll=window.scrollY;
    const focused=document.activeElement;
    const restoreSelector=focused?.dataset.campaign&&view==='landing'?`#campaign-tab-${arg}`:focused?.id?`#${focused.id}`:focused?.dataset.level?`[data-level="${focused.dataset.level}"]`:focused?.dataset.step?`[data-step="${focused.dataset.step}"]`:null;
    const valid=['intro','story','wardrobe','detail','poses','build','landing','references'].includes(view)?view:'intro';
    main.dataset.view=valid;
    teardownAutoplay();
    teardownLandingSpy();
    if(cardDialog.open)cardDialog.close();
    main.innerHTML=valid==='build'?S.studyPage(arg):valid==='story'?renderStory(arg):valid==='wardrobe'?renderWardrobe(arg):valid==='detail'?renderDetail(arg):valid==='poses'?renderPoses(arg):valid==='landing'?renderLanding(arg):valid==='references'?renderReferences():renderIntro();
    document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===(valid==='detail'?'wardrobe':valid))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    document.querySelector('#primary-nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');closeGuide();
    document.title=`${({intro:'Meet Max',story:'The Character',wardrobe:'The Wardrobe',detail:`${level(state.selected).name} · Costume Study`,poses:'Pose & Gesture',build:'Character Build',landing:'Landing Page Concepts',references:'The Archive'})[valid]} — NetBet MAX`;
    if(previous===valid&&(valid==='wardrobe'||valid==='detail'||(valid==='landing'&&focused?.dataset.campaign))){window.scrollTo({top:oldScroll,behavior:'instant'});if(restoreSelector)document.querySelector(restoreSelector)?.focus({preventScroll:true});}else{window.scrollTo({top:0,behavior:'instant'});if(previous)main.focus({preventScroll:true});}
    if(valid==='references'&&arg==='sources')requestAnimationFrame(()=>document.querySelector('#sources').scrollIntoView());
    if(valid==='story'&&arg==='motion')requestAnimationFrame(()=>document.querySelector('#motion').scrollIntoView());
    if(valid==='landing'){const requested=state.campaign,rail=document.querySelector('.campaign-tabs'),tab=document.querySelector('#campaign-tab-'+requested),page=document.querySelector('#landing-page-'+requested);if(rail&&tab)rail.scrollLeft=Math.max(0,tab.offsetLeft-(rail.clientWidth-tab.clientWidth)/2);if(arg&&page){page.scrollIntoView({block:'start'});requestAnimationFrame(()=>{page.scrollIntoView({block:'start'});setActiveLanding(requested);initLandingSpy();});}}
    initReveals();
    initAutoplay();
    if(valid!=='landing'||!arg)initLandingSpy();
    document.querySelector('#announcement').textContent=valid==='wardrobe'||valid==='detail'?`${level(state.selected).name}. ${level(state.selected).outfit?'Outfit available.':'Matching outfit not supplied.'}`:document.title;
  }
  function selectLevel(slug){const view=main.dataset.view==='detail'?'detail':'wardrobe';location.hash=`${view}/${slug}`;}
  function setAnnotation(index){const l=level(state.selected);if(!l.outfit)return;state.annotation=index;document.querySelectorAll('[data-annotation]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.annotation)===index));document.querySelectorAll('[data-line]').forEach(p=>p.classList.toggle('selected-line',Number(p.dataset.line)===index));document.querySelector('#annotation-panel').innerHTML=annotationPanel(l,index);}
  function setPromotionAnnotation(index){document.querySelectorAll('[data-promotion-annotation]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.promotionAnnotation)===index));document.querySelectorAll('[data-promotion-line]').forEach(p=>p.classList.toggle('selected-line',Number(p.dataset.promotionLine)===index));document.querySelector('#promotion-annotation-panel').innerHTML=P.promotionDetail(index);}
  function setPose(id,focus=false){state.pose=id;document.querySelectorAll('[data-pose]').forEach(b=>{const sel=b.dataset.pose===id;b.setAttribute('aria-selected',sel);b.tabIndex=sel?0:-1;if(sel&&focus)b.focus();});const panel=document.querySelector('#pose-panel');panel.innerHTML=poseContent(id);panel.setAttribute('aria-labelledby',`tab-${id}`);}
  function galleryUpdate(){document.querySelector('#reference-grid').innerHTML=referenceItems();document.querySelector('#archive-count').textContent=`${filteredRefs().length} of ${R.length} unique images · select an image to inspect`;}
  function fitViewer(){const im=document.querySelector('#viewer-image'),area=document.querySelector('.viewer-scroll');if(!im.naturalWidth)return;const ratio=Math.min((area.clientWidth-30)/im.naturalWidth,(area.clientHeight-24)/im.naturalHeight);state.fit={w:im.naturalWidth*ratio,h:im.naturalHeight*ratio};applyZoom();}
  function applyZoom(point){const im=document.querySelector('#viewer-image'),figure=document.querySelector('#viewer-figure'),canvas=document.querySelector('.viewer-canvas'),area=document.querySelector('.viewer-scroll');const w=state.fit.w*state.zoom,h=state.fit.h*state.zoom;im.style.width=`${w}px`;im.style.height=`${h}px`;figure.style.width=`${w}px`;figure.style.height=`${h}px`;canvas.style.width=`${Math.max(w+30,area.clientWidth)}px`;canvas.style.height=`${Math.max(h+24,area.clientHeight)}px`;document.querySelector('#zoom-value').textContent=`${Math.round(state.zoom*100)}%`;document.querySelector('#zoom-in').disabled=state.zoom>=5;document.querySelector('#zoom-out').disabled=state.zoom<=1;if(point)requestAnimationFrame(()=>{area.scrollLeft=figure.offsetLeft+w*point[0]/100-area.clientWidth/2;area.scrollTop=figure.offsetTop+h*point[1]/100-area.clientHeight/2;});}
  function showViewerItem(point){const r=state.viewerItems[state.viewerIndex],im=document.querySelector('#viewer-image');state.zoom=point?3:1;document.querySelector('#viewer-title').textContent=r.title;document.querySelector('#viewer-caption').textContent=r.description;document.querySelector('#viewer-original').href=r.original;document.querySelector('#viewer-kicker').textContent=r.kind==='badge'?'Official Figma emblem':r.kind==='outfit'?'Family wardrobe · official chest emblem':r.kind==='study'?'Generated character / environment study':r.origin==='Generated proposal'?'Generated ambassador proposal':'Original reference artwork';const sourceLink=document.querySelector('#viewer-source');sourceLink.hidden=!r.figma;if(r.figma)sourceLink.href=r.figma;document.querySelector('#viewer-prev').disabled=state.viewerItems.length<2||state.viewerIndex===0;document.querySelector('#viewer-next').disabled=state.viewerItems.length<2||state.viewerIndex===state.viewerItems.length-1;const crest=document.querySelector('#viewer-emblem');const attached=r.kind==='outfit'||(r.kind==='study'&&r.emblem);crest.hidden=!attached;if(attached){const l=level(r.level),e=r.kind==='study'?r.emblem:l.outfit.emblem;crest.src=l.badge;crest.alt=l.name+' official chest emblem';crest.style.left=e.x+'%';crest.style.top=e.y+'%';crest.style.width=e.width+'%';crest.style.transform='translate(-50%,-50%) rotate('+(e.rotation||0)+'deg)';}document.querySelector('#viewer-original').textContent=attached?'Open artwork base ↗':'Open original ↗';im.alt=r.description;im.onload=()=>{fitViewer();if(point)applyZoom(point);else document.querySelector('.viewer-scroll').scrollTo(0,0);};im.src=r.original;}
  function openImages(items,id,point){state.lastFocus=document.activeElement;state.viewerItems=items;state.viewerIndex=Math.max(0,items.findIndex(r=>r.id===id));document.body.classList.add('modal-open');viewer.showModal();showViewerItem(point);document.querySelector('#viewer-close').focus();}
  function openOutfit(slug,point){const l=level(slug),r=ref(l.outfit.ref);openImages([{...r,kind:'outfit',level:slug,title:l.name+' · '+l.outfit.pose,description:r.description+' '+l.name+' official emblem attached below NB. '+l.outfit.change}],r.id,point);}
  function openStudio(id){const r=ref(id),meta=window.MAX_STUDIO_ASSETS[id];openImages([{...r,kind:'study',level:meta?.level,emblem:meta?.emblem}],id);}
  function openBadge(slug){const l=level(slug);openImages([{id:slug,kind:'badge',title:`${l.name} · ${l.wingLabel}`,original:l.badge,figma:`https://www.figma.com/design/7XyxLDzYaGxD4i81uIeXIZ/Loyalty-Plan?node-id=${l.node.replace(':','-')}`,description:`Official Figma badge. Level ${l.number} of 28; source asset label: ${l.sourceName}. ${D.families.find(f=>f.id===l.family).note} Node ${l.node}.`}],slug);}
  function garmentList(items){const labels=['Coat & silhouette','Waistcoat & neckwear','Trousers','Footwear','Accessories & emblem'];return `<dl class="card-modal-list">${items.map((item,i)=>`<div><dt>${labels[i]||'Detail'}</dt><dd>${esc(item)}</dd></div>`).join('')}</dl>`;}
  function showPoseDialog(id){const p=D.poses.find(p=>p.id===id);if(!p)return;state.lastFocus=document.activeElement;const art=p.level?C.character(p.level,'',true):img(p.ref,'',true);document.querySelector('#card-dialog-content').innerHTML=`<div class="card-modal-layout"><figure class="card-modal-art">${art}<figcaption>${esc(p.status||'Supplied pose study')}</figcaption></figure><div class="card-modal-copy"><span class="eyebrow">Gesture ${pad(D.poses.indexOf(p)+1)} / Pose study</span><h2 id="card-dialog-title">${esc(p.title)}</h2><p class="card-modal-lead">${esc(p.gesture)}</p><dl class="card-modal-summary"><div><dt>Intended interface role</dt><dd>${esc(p.context)}</dd></div><div><dt>Proposed voice</dt><dd>${esc(p.voice)}</dd></div><div><dt>Production note</dt><dd>${esc(p.note)}</dd></div></dl>${p.level?`<div class="card-modal-actions"><a class="button" href="#detail/${p.level}">Open the costume study →</a><button type="button" class="text-link" data-outfit="${p.level}">Enlarge artwork ↗</button></div>`:''}</div></div>`;closeGuide();document.body.classList.add('modal-open');cardDialog.showModal();document.querySelector('[data-close-card]').focus();}
  function closeGuide(){document.querySelector('#guide-panel').hidden=true;document.querySelector('#guide-toggle').setAttribute('aria-expanded','false');}
  function campaignAction(id){
    const c=window.MAX_AMBASSADOR.campaigns.find(c=>c.id===id);
    if(c.action==='wardrobe'){location.hash='wardrobe/'+c.level;return;}
    state.lastFocus=document.activeElement;
    const content=c.action==='reserve'?`<h2 id="campaign-dialog-title">Your Reserve reward,<br>explained.</h2><p><strong>£20 casino bonus</strong> is listed as the Reserve level-up prize.</p><ul><li>10× wagering requirement.</li><li>Maximum win: £100.</li><li>Eligibility, expiry and all current programme terms apply.</li></ul><p class="fine-note">Creative offer example, checked against the official level schedule on ${window.MAX_AMBASSADOR.sourceChecked}. This presentation does not show your account eligibility or allow a claim.</p>`:`<h2 id="campaign-dialog-title">Weekly rewards,<br>at a glance.</h2><p>Playback and cashback benefits can be available according to your level and eligibility.</p><ul><li>The live hub shows your account’s available rewards.</li><li>Check the amount, timing and conditions before claiming.</li><li>Max helps explain the programme and where to find the details.</li></ul><p class="fine-note">A proposed assistant explanation. Current official terms govern the benefits.</p>`;
    document.querySelector('#campaign-dialog-content').innerHTML=content+`<a class="button" href="${window.MAX_AMBASSADOR.source}" target="_blank" rel="noopener">Read the official details ↗</a>`;
    closeGuide();document.body.classList.add('modal-open');document.querySelector('#campaign-dialog').showModal();
  }
  document.addEventListener('click',e=>{
    const landingLink=e.target.closest('[data-campaign-link]');
    if(landingLink?.dataset?.campaignLink&&main.dataset.view==='landing'){
      e.preventDefault();const id=landingLink.dataset.campaignLink,page=document.querySelector('#landing-page-'+id);setActiveLanding(id);page?.scrollIntoView({block:'start',behavior:reducedMotion.matches?'instant':'smooth'});return;
    }
    const b=e.target.closest('button');if(!b)return;
    if(b.hasAttribute?.('data-close-card')){cardDialog.close();return;}
    if(b.dataset.studioImage){openStudio(b.dataset.studioImage);return;}
    if(b.dataset.faceFilter){document.querySelector('#expression-grid').innerHTML=S.expressionGrid(b.dataset.faceFilter);document.querySelectorAll('[data-face-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));return;}
    if(b.dataset.introModel!==undefined){C.choose('intro',Number(b.dataset.introModel));refreshCarousel('intro');return;}
    if(b.dataset.introPose){I.chooseView(C.positions.intro,b.dataset.introPose);refreshCarousel('intro');document.querySelector(`[data-intro-pose="${b.dataset.introPose}"]`)?.focus({preventScroll:true});return;}
    if(b.dataset.carouselStep){C.move(b.dataset.carousel,Number(b.dataset.carouselStep));refreshCarousel(b.dataset.carousel);return;}
    if(b.dataset.carouselRank){C.chooseRank(b.dataset.carousel,b.dataset.carouselRank);refreshCarousel(b.dataset.carousel);document.querySelector(`[data-carousel="${b.dataset.carousel}"][data-carousel-rank="${b.dataset.carouselRank}"]`)?.focus({preventScroll:true});return;}
    if(b.dataset.tour){toggleAutoplay('carousel:'+b.dataset.tour);return;}
    if(b.dataset.shelfTour){toggleAutoplay('shelf:'+b.dataset.shelfTour);return;}
    if(b.dataset.shelf){document.querySelector('#wardrobe-shelf').scrollBy({left:Number(b.dataset.shelf)*document.querySelector('#wardrobe-shelf').clientWidth*.8,behavior:reducedMotion.matches?'instant':'smooth'});return;}
    if(b.dataset.outfit){if(cardDialog.open)cardDialog.close();openOutfit(b.dataset.outfit,b.dataset.focus?.split(',').map(Number));return;}
    if(b.dataset.campaign){location.hash='landing/'+b.dataset.campaign;return;}
    if(b.dataset.device){state.device=b.dataset.device;document.querySelector('#campaign-preview').classList.toggle('device-mobile',state.device==='mobile');document.querySelectorAll('[data-device]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.device===state.device));return;}
    if(b.dataset.campaignAction){campaignAction(b.dataset.campaignAction);return;}
    if(b.hasAttribute?.('data-close-campaign')){document.querySelector('#campaign-dialog').close();return;}
    if(b.hasAttribute?.('data-close-guide')){closeGuide();document.querySelector('#guide-toggle').focus();return;}
    if(b.dataset.level){selectLevel(b.dataset.level);return;}
    if(b.dataset.step){const next=D.levels[level(state.selected).number-1+Number(b.dataset.step)];if(next)selectLevel(next.slug);return;}
    if(b.dataset.promotionAnnotation!==undefined){setPromotionAnnotation(Number(b.dataset.promotionAnnotation));return;}
    if(b.dataset.annotation!==undefined){setAnnotation(Number(b.dataset.annotation));return;}
    if(b.dataset.pose){showPoseDialog(b.dataset.pose);return;}
    if(b.dataset.image){openImages([ref(b.dataset.image)],b.dataset.image,b.dataset.focus?.split(',').map(Number));return;}
    if(b.dataset.galleryImage){openImages(filteredRefs(),b.dataset.galleryImage);return;}
    if(b.dataset.badge){openBadge(b.dataset.badge);return;}
    if(b.dataset.filter){state.filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));galleryUpdate();return;}
  });
  document.addEventListener('change',e=>{if(e.target.id==='study-select'){location.hash='build/'+e.target.value;return;}if(e.target.dataset?.carouselSelect){C.choose(e.target.dataset.carouselSelect,Number(e.target.value));refreshCarousel(e.target.dataset.carouselSelect);return;}if(e.target.id==='level-select'||e.target.id==='detail-select')selectLevel(e.target.value);if(e.target.id==='family-select')selectLevel(D.families.find(f=>f.id===e.target.value).slugs[0]);});
  document.addEventListener('input',e=>{if(e.target.matches('.archive-search')){state.search=e.target.value;galleryUpdate();}});
  document.querySelector('.menu-toggle').addEventListener('click',e=>{const open=document.querySelector('#primary-nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('#primary-nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');}});
  document.addEventListener('keydown',e=>{if(e.target.matches('[data-campaign]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const list=window.MAX_AMBASSADOR.campaigns;let i=list.findIndex(c=>c.id===state.campaign);i=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;location.hash='landing/'+list[i].id;requestAnimationFrame(()=>document.querySelector('#campaign-tab-'+list[i].id)?.focus());}if(e.key==='Escape')closeGuide();});
  document.querySelector('#guide-toggle').addEventListener('click',()=>{const panel=document.querySelector('#guide-panel');panel.hidden=!panel.hidden;document.querySelector('#guide-toggle').setAttribute('aria-expanded',!panel.hidden);});
  document.querySelector('#campaign-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');state.lastFocus?.focus({preventScroll:true});});
  cardDialog.addEventListener('click',e=>{if(e.target===cardDialog){const b=cardDialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)cardDialog.close();}});
  cardDialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');state.lastFocus?.focus({preventScroll:true});});
  document.querySelector('#viewer-close').addEventListener('click',()=>viewer.close());
  viewer.addEventListener('click',e=>{if(e.target===viewer){const b=viewer.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)viewer.close();}});
  viewer.addEventListener('close',()=>{document.body.classList.remove('modal-open');state.lastFocus?.focus({preventScroll:true});});
  document.querySelector('#zoom-in').addEventListener('click',()=>{state.zoom=Math.min(5,state.zoom+.5);applyZoom([50,50]);});
  document.querySelector('#zoom-out').addEventListener('click',()=>{state.zoom=Math.max(1,state.zoom-.5);applyZoom([50,50]);});
  document.querySelector('#zoom-reset').addEventListener('click',()=>{state.zoom=1;applyZoom([50,50]);});
  document.querySelector('#viewer-prev').addEventListener('click',()=>{if(state.viewerIndex>0){state.viewerIndex--;showViewerItem();}});
  document.querySelector('#viewer-next').addEventListener('click',()=>{if(state.viewerIndex<state.viewerItems.length-1){state.viewerIndex++;showViewerItem();}});
  window.addEventListener('resize',()=>{if(viewer.open)fitViewer();});

  const reducedMotion=window.matchMedia?window.matchMedia('(prefers-reduced-motion: reduce)'):{matches:false};
  let autoplayTimer=null,autoplayTarget=null,autoplayObserver=null,revealObserver=null,landingObserver=null,swipe=null;
  const pausedAutoplay=new Set(),visibleAutoplay=new Set();
  function refreshCarousel(key){
    const body=document.querySelector('#carousel-'+key);body.innerHTML=C.carouselBody(key);
    if(key==='intro')document.querySelectorAll('[data-intro-model]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.introModel)===C.positions.intro));
    document.querySelector(`[data-carousel-counter="${key}"]`).textContent=pad(C.positions[key]+1)+' / '+pad(C.sequences[key].length);
    const picker=document.querySelector(`[data-carousel-select="${key}"]`);if(picker)picker.value=String(C.positions[key]);
    document.querySelector(`[data-carousel-progress="${key}"]`).style.left=(C.positions[key]*100/C.sequences[key].length)+'%';
  }
  function stopAutoplayTimer(){if(autoplayTimer)window.clearInterval(autoplayTimer);autoplayTimer=null;autoplayTarget=null;}
  function teardownAutoplay(){stopAutoplayTimer();if(autoplayObserver)autoplayObserver.disconnect();autoplayObserver=null;visibleAutoplay.clear();}
  function teardownLandingSpy(){if(landingObserver)landingObserver.disconnect();landingObserver=null;}
  function setActiveLanding(id){
    const rail=document.querySelector('.campaign-tabs'),tab=document.querySelector('#campaign-tab-'+id);if(!rail||!tab)return;
    state.campaign=id;
    if(location.hash!=='#landing/'+id)window.history?.replaceState(null,'','#landing/'+id);
    document.querySelectorAll('[data-campaign-link]').forEach(link=>{if(link.dataset.campaignLink===id)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});
    document.querySelectorAll('.landing-page-entry').forEach(page=>page.classList.toggle('is-selected',page.id==='landing-page-'+id));
    rail.scrollTo({left:Math.max(0,tab.offsetLeft-(rail.clientWidth-tab.clientWidth)/2),behavior:reducedMotion.matches?'instant':'smooth'});
  }
  function initLandingSpy(){
    teardownLandingSpy();if(main.dataset.view!=='landing'||!('IntersectionObserver' in window))return;
    const pages=[...document.querySelectorAll('.landing-page-entry')];if(!pages.length)return;
    landingObserver=new window.IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio);if(visible.length)setActiveLanding(visible[0].target.id.replace('landing-page-',''));},{rootMargin:'-82px 0px -48% 0px',threshold:[.08,.2,.4,.6]});
    pages.forEach(page=>landingObserver.observe(page));
  }
  function targetFor(el){return el.dataset.carouselRoot?'carousel:'+el.dataset.carouselRoot:'shelf:'+el.dataset.shelfRoot;}
  function updateAutoplayControls(){
    document.querySelectorAll('[data-tour]').forEach(b=>{const target='carousel:'+b.dataset.tour,enabled=!pausedAutoplay.has(target)&&!reducedMotion.matches;b.disabled=reducedMotion.matches;b.setAttribute('aria-pressed',String(enabled));b.textContent=reducedMotion.matches?'Manual browsing':enabled?'Pause tour':'Play tour';const body=document.querySelector('#carousel-'+b.dataset.tour);if(body)body.setAttribute('aria-live',enabled?'off':'polite');});
    document.querySelectorAll('[data-shelf-tour]').forEach(b=>{const target='shelf:'+b.dataset.shelfTour,enabled=!pausedAutoplay.has(target)&&!reducedMotion.matches;b.disabled=reducedMotion.matches;b.setAttribute('aria-pressed',String(enabled));b.textContent=reducedMotion.matches?'Manual browsing':enabled?'Pause tour':'Play tour';});
  }
  function advanceShelf(){const rail=document.querySelector('#wardrobe-shelf');if(!rail)return;const step=rail.clientWidth*.8;if(rail.scrollLeft+rail.clientWidth>=rail.scrollWidth-4)rail.scrollTo({left:0,behavior:reducedMotion.matches?'instant':'smooth'});else rail.scrollBy({left:step,behavior:reducedMotion.matches?'instant':'smooth'});}
  function startAutoplay(target){if(document.hidden||reducedMotion.matches||pausedAutoplay.has(target)||autoplayTarget===target)return;stopAutoplayTimer();autoplayTarget=target;autoplayTimer=window.setInterval(()=>{if(target.startsWith('carousel:')){const key=target.slice(9);C.move(key,1);refreshCarousel(key);}else advanceShelf();},2500);}
  function toggleAutoplay(target){if(reducedMotion.matches)return;if(pausedAutoplay.has(target)){pausedAutoplay.delete(target);updateAutoplayControls();if(visibleAutoplay.has(target)||!('IntersectionObserver' in window))startAutoplay(target);}else{pausedAutoplay.add(target);if(autoplayTarget===target)stopAutoplayTimer();updateAutoplayControls();}}
  function initAutoplay(){
    teardownAutoplay();updateAutoplayControls();
    if(document.hidden||reducedMotion.matches)return;
    const roots=[...document.querySelectorAll('[data-carousel-root],[data-shelf-root]')];if(!roots.length)return;
    if('IntersectionObserver' in window){autoplayObserver=new window.IntersectionObserver(entries=>entries.forEach(entry=>{const target=targetFor(entry.target);if(entry.isIntersecting){visibleAutoplay.add(target);startAutoplay(target);}else{visibleAutoplay.delete(target);if(autoplayTarget===target)stopAutoplayTimer();}}),{threshold:.35});roots.forEach(root=>autoplayObserver.observe(root));}
    else{const target=targetFor(roots[0]);visibleAutoplay.add(target);startAutoplay(target);}
  }
  function initReveals(){
    if(revealObserver)revealObserver.disconnect();
    if(reducedMotion.matches||!('IntersectionObserver' in window))return;
    revealObserver=new window.IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');revealObserver.unobserve(e.target);}}),{threshold:.06});
    document.querySelectorAll('.section-spaced,.rank-summary,.ensemble-record').forEach(el=>{el.classList.add('reveal-ready');revealObserver.observe(el);});
  }
  document.addEventListener('keydown',e=>{const key=e.target.dataset?.carouselKeys;if(key&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();if(e.key==='Home')C.choose(key,0);else if(e.key==='End')C.choose(key,C.sequences[key].length-1);else C.move(key,e.key==='ArrowRight'?1:-1);refreshCarousel(key);}});
  document.addEventListener('pointerdown',e=>{const target=e.target.closest('[data-carousel-keys]');if(target&&!e.target.closest('button,a,select'))swipe={key:target.dataset.carouselKeys,x:e.clientX,y:e.clientY};});
  document.addEventListener('pointerup',e=>{if(!swipe)return;const dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.4){C.move(swipe.key,dx<0?1:-1);refreshCarousel(swipe.key);}swipe=null;});
  document.addEventListener('pointercancel',()=>{swipe=null;});
  document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAutoplayTimer();else initAutoplay();});
  reducedMotion.addEventListener?.('change',()=>{teardownAutoplay();initReveals();initAutoplay();});

  window.addEventListener('hashchange',route);route();
})();
